export interface ResearchMemoryState { version: string; entries: ResearchMemoryEntry[] }
export function installResearchMemory(existing?: ResearchMemoryState): ResearchMemoryState {
  if (existing?.version === MEMORY_VERSION && Array.isArray(existing.entries)) return existing;
  const entries = Array.isArray(existing?.entries) ? existing.entries.map((entry) => {
    // Update only the obsolete status sentence; preserve any other user edits.
    if (entry?.id === "session-user-wing-learning-diagnostic" && typeof entry.limitations === "string" && entry.limitations.includes("Полный долгий прогон ещё не готов.")) {
      return { ...entry, limitations: entry.limitations.replace("Полный долгий прогон ещё не готов.", "На момент диагностики полный долгий прогон ещё не был проведён; результат серии 59 описан отдельно.") };
    }
    if (entry?.id === "session-long-user-wing-context-plan" && [
      "подготовлен BAT и read-only протокол; пользовательский запуск ещё не получен",
      "выполнено по присланному тексту ОТЧЕТ.txt; оригинальные файлы серии 61 не получены",
    ].includes(entry.status)) {
      const current = RESEARCH_MEMORY.find((item) => item.id === "session-long-user-wing-context-plan");
      return current ? { ...entry, title: current.title, status: current.status, source: current.source, results: current.results, limitations: current.limitations, files: [...current.files] } : entry;
    }
    if (entry?.id === "session-long-user-wing-user-result") {
      const oldSource = "NPZ, SQLite, имена выбранных JSON и покадровые файлы независимо не получены.";
      const oldLimit = "Для анализа времён нужен test_002/predictions.csv, NPZ не нужен.";
      const source = typeof entry.source === "string" ? entry.source.replace(oldSource, "NPZ, SQLite и имена выбранных JSON независимо не получены; позже пользователь приложил CSV новой проверки.") : entry.source;
      const limitations = typeof entry.limitations === "string" ? entry.limitations.replace(oldLimit, "Пользователь позже прислал CSV новой проверки; покадровый анализ сохранён отдельно, NPZ не получен.") : entry.limitations;
      const status = entry.status === "completed по присланным текстам ИТОГ и summary; исходные файлы не проверены" ? "completed по присланным текстам ИТОГ и summary; модель и база не проверены" : entry.status;
      return source !== entry.source || limitations !== entry.limitations || status !== entry.status ? { ...entry, source, limitations, status } : entry;
    }
    return entry;
  }) : [];
  const present = new Set(entries.map((entry) => entry?.id));
  return { version: MEMORY_VERSION, entries: [...entries, ...RESEARCH_MEMORY.filter((entry) => !present.has(entry.id)).map((entry) => ({ ...entry, files: [...entry.files] }))] };
}

export function memoryForIdea(memory: ResearchMemoryState | undefined, ideaId: string): ResearchMemoryEntry[] {
  return (memory?.entries ?? []).filter((entry) => entry && entry.ideaId === ideaId);
}
